class Solution {
  public int specialTriplets(int[] nums) {
    final long MOD = 1_000_000_007L;
    int[] left = new int[200001], right = new int[200001];
    for (int x : nums) right[x]++;
    long ans = 0;
    for (int x : nums) {
      right[x]--;
      if (2 * x <= 200000) ans = (ans + (long) left[2 * x] * right[2 * x]) % MOD;
      left[x]++;
    }
    return (int) ans;
  }
}
